"""Assemble a standalone TeX file. Run from any working directory."""
from pathlib import Path
import re
import json

ROOT = Path(__file__).resolve().parents[1]
preamble = r'''% !TeX program = xelatex
% Generated by scripts/build.py; edit chapters/*.tex and code/*.cpp.
\documentclass[UTF8,11pt,a4paper,fontset=none]{ctexart}
\usepackage[margin=2.2cm]{geometry}
\usepackage{fontspec}
\IfFontExistsTF{FandolSong-Regular}{
\setCJKmainfont{FandolSong-Regular}[BoldFont=FandolHei-Regular]
\setCJKsansfont{FandolHei-Regular}\setCJKmonofont{FandolSong-Regular}
}{\setCJKmainfont{SimSun}[BoldFont=SimHei]\setCJKsansfont{SimHei}\setCJKmonofont{SimSun}}
\usepackage{amsmath,amssymb,booktabs,longtable,array,enumitem,xcolor,listings}
\usepackage{fancyvrb,needspace,tcolorbox}
\usepackage[xetex]{accsupp}
\DefineVerbatimEnvironment{Sample}{Verbatim}{samepage=true,fontsize=\small}
\tcbset{samplebox/.style={colback=blue!2!white,colframe=blue!35!black,colbacktitle=blue!8!white,coltitle=black,fonttitle=\bfseries,boxrule=0.5pt,arc=1mm,left=3mm,right=3mm,top=1mm,bottom=1mm,before skip=6pt,after skip=6pt}}
\usepackage{hyperref}
\hypersetup{colorlinks=true,linkcolor=black,urlcolor=blue!55!black,pdftitle={CCF-CSP前三题备考讲义}}
\setlength{\parskip}{0.3em}\setlength{\emergencystretch}{3em}
\renewcommand{\arraystretch}{1.2}\setlength{\tabcolsep}{5pt}
\setlist{nosep,topsep=0.3em,leftmargin=2em}
\pagestyle{plain}\setcounter{tocdepth}{2}
\newcolumntype{P}[1]{>{\raggedright\arraybackslash}p{#1}}
\ctexset{section={format=\Large\bfseries},subsection={format=\large\bfseries},subsubsection={format=\normalsize\bfseries}}
\definecolor{CodeKeyword}{HTML}{164D9C}
\definecolor{CodeString}{HTML}{A13D20}
\definecolor{CodeComment}{HTML}{326746}
\definecolor{CodeFunction}{HTML}{71408A}
\definecolor{CodeBackground}{HTML}{F7F9FC}
% Keep line numbers visible, but omit them from PDF text selection/copy.
\newcommand{\noncopynumber}[1]{\BeginAccSupp{method=escape,ActualText={}}#1\EndAccSupp{}}
\lstset{language=C++,keywordstyle=\color{CodeKeyword}\bfseries,stringstyle=\color{CodeString},commentstyle=\color{CodeComment}\itshape,backgroundcolor=\color{CodeBackground},emph={scanf,printf,puts,fgets,strcmp,strlen,strcpy,strcspn,strtok,sort,unique,lower_bound,upper_bound,reverse,fill,min,max,swap,push_back,pop_back,insert,erase,find,begin,end,c_str},emphstyle=\color{CodeFunction},basicstyle=\ttfamily\footnotesize\linespread{1}\selectfont,breaklines=true,columns=fullflexible,keepspaces=true,showstringspaces=false,numbers=left,numberstyle=\tiny\noncopynumber,numbersep=7pt,xleftmargin=1.5em,frame=single,rulecolor=\color{black!20},tabsize=4}
\newcommand{\example}[1]{\subsection{例题 #1}}
\newcommand{\exercise}{\subsection{练习与解答}}
\newcommand{\prob}[1]{\href{https://www.luogu.com.cn/problem/#1}{\texttt{#1}}}
\newcommand{\practice}[2]{\par\noindent\textbf{同类练习（在线做题）：}\href{https://www.luogu.com.cn/problem/#1}{#1\quad #2}。\par}
\newcommand{\training}[2]{\par\noindent\textbf{专题题单：}\href{https://www.luogu.com.cn/training/#1}{#2（#1）}。\par}
\newcommand{\csp}[2]{\ifcsname cspurl@#1\endcsname\href{\csname cspurl@#1\endcsname}{#2（\texttt{#1}，AcWing）}\else\href{https://oj.shumeng.tech/p/#1}{#2（\texttt{#1}）}\fi}
\newcommand{\ojpractice}[2]{\par\noindent\textbf{真题练习：}\csp{#1}{#2}。\par}
\makeatletter\@addtoreset{section}{part}\makeatother
\renewcommand{\theHsection}{\thepart.\arabic{section}}
\newcommand{\important}[1]{\par\noindent\textbf{#1}\par}
\title{\textbf{CCF-CSP 前三题备考讲义}}
\author{第一题：基础实现\quad 第二题：工具与算法\quad 第三题：综合模拟}
\date{2026年10月11日}
\begin{document}\maketitle
'''

# Preserve verified original portals when a Shumeng counterpart is unavailable.
for entry in json.loads((ROOT / 'data/exercise-links.json').read_text(encoding='utf-8-sig')):
    url = entry.get('preferred_url', '')
    if entry.get('certification_id') and url and not url.startswith('https://oj.shumeng.tech/'):
        definition = (r'\expandafter\def\csname cspurl@' + entry['certification_id']
                      + r'\endcsname{' + url + '}\n')
        preamble = preamble.replace(r'\begin{document}', definition + r'\begin{document}', 1)


def format_sample(match):
    content = match.group(1).strip('\n')
    groups = re.split(r'^另一组输入\n', content, flags=re.M)
    boxes = []
    for i, group in enumerate(groups):
        if i:
            group = '输入\n' + group
        group = group.replace('\n另一组输出\n', '\n输出\n').rstrip('\n')
        if group.startswith('输入\n') and '\n输出\n' in group:
            input_text, output_text = group[3:].split('\n输出\n', 1)
            title = '输入输出样例' if len(groups) == 1 else f'输入输出样例 {i + 1}'
            boxes.append('\n'.join([
                r'\begin{tcolorbox}[samplebox,title={' + title + '}]',
                r'\textbf{样例输入}', r'\begin{Sample}', input_text, r'\end{Sample}',
                r'\tcblower', r'\textbf{样例输出}', r'\begin{Sample}', output_text,
                r'\end{Sample}', r'\end{tcolorbox}',
            ]))
        else:
            boxes.append('\n'.join([
                r'\begin{tcolorbox}[samplebox,title={语法规则}]',
                r'\begin{Sample}', group, r'\end{Sample}', r'\end{tcolorbox}',
            ]))
    return '\n'.join(boxes)


def expand(match):
    name = match.group(1)
    content = (ROOT / 'code' / name).read_text(encoding='utf-8').rstrip()
    return '\n'.join([
        r'\par\noindent\begin{minipage}{\linewidth}',
        r'\textbf{完整参考实现}\quad\texttt{' + name.replace('_', r'\_') + '}',
        r'\begin{lstlisting}', content, r'\end{lstlisting}',
        r'\end{minipage}\par', '',
    ])


# Three study parts; filenames retain their original identities.
order = ['00-preface.tex', '01-basics.tex', 'first-true.tex', 'first-summary.tex',
         '02-simulation.tex', 'first-practice.tex', 'second-foundations.tex',
         '05-prefix.tex', '06-binary.tex', '07-greedy.tex', '08-search.tex',
         '09-dp.tex', '10-knapsack.tex', '03-stl.tex', 'second-true.tex',
         'second-summary.tex', 'second-practice.tex', 'team-practice.tex', '04-strings.tex',
         '11-comprehensive.tex', '12-practice.tex', '13-extensions.tex']
parts = []
for filename in order:
    path = ROOT / 'chapters' / filename
    text = path.read_text(encoding='utf-8-sig')
    if path.name != '00-preface.tex':
        text = text.replace('\\newpage', '\\par\\bigskip')
        text = text.replace('\\section{', '\\Needspace{7\\baselineskip}\\section{')
    if path.name == 'team-practice.tex':
        text = text.replace('\\subsubsection{', '\\Needspace{8\\baselineskip}\\subsubsection{')
    text = re.sub(r'\\begin\{verbatim\}\n(.*?)\\end\{verbatim\}', format_sample, text, flags=re.S)
    text = re.sub(
        r'\\begin\{lstlisting\}(.*?)\\end\{lstlisting\}',
        lambda m: '\\par\\noindent\\begin{minipage}{\\linewidth}\n' + m.group(0) + '\n\\end{minipage}\\par',
        text, flags=re.S,
    )
    parts.append('% ===== ' + path.name + ' =====\n' + re.sub(r'\\Code\{([^}]+)\}', expand, text))
(ROOT / 'main.tex').write_text(preamble + '\n'.join(parts) + '\n\\end{document}\n', encoding='utf-8')
print(f'Assembled {len(parts)} chapter files into main.tex')
